import{_ as e,o as n,c as t,ag as i}from"./chunks/framework.Dx86EdC1.js";const m=JSON.parse('{"title":"Data Kartu Keluarga","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/kartu-keluarga.md","filePath":"panduan-pengguna/kartu-keluarga.md","lastUpdated":1791382762000}'),l={name:"panduan-pengguna/kartu-keluarga.md"};function r(u,a,s,o,d,g){return n(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="data-kartu-keluarga" tabindex="-1">Data Kartu Keluarga <a class="header-anchor" href="#data-kartu-keluarga" aria-label="Permalink to &quot;Data Kartu Keluarga&quot;">​</a></h1><p>Modul <strong>Buku Induk Kartu Keluarga</strong> dikelola di menu <strong>Kependudukan → Kartu Keluarga</strong> (<code>/admin/families</code>).</p><h2 id="daftar-kk" tabindex="-1">Daftar KK <a class="header-anchor" href="#daftar-kk" aria-label="Permalink to &quot;Daftar KK&quot;">​</a></h2><p>Halaman daftar menampilkan seluruh KK dengan pencarian nomor KK/nama kepala keluarga dan filter <strong>Dusun</strong>.</p><div class="info custom-block"><p class="custom-block-title">Hak akses berbasis wilayah</p><p>Akun <strong>Ketua RT</strong> hanya melihat KK di RT-nya sendiri (<em>scoped access</em>). Jika Anda operator perangkat desa, seluruh data terlihat. Dasar hukum: kebutuhan informasi (<em>need-to-know</em>) sesuai UU PDP No. 27/2022.</p></div><h2 id="menambah-kk" tabindex="-1">Menambah KK <a class="header-anchor" href="#menambah-kk" aria-label="Permalink to &quot;Menambah KK&quot;">​</a></h2><ol><li>Klik <strong>Tambah Kartu Keluarga</strong>.</li><li>Isi: <ul><li><strong>Nomor KK</strong> — 16 digit, wajib angka, disimpan sebagai <em>string</em> (nol di depan aman).</li><li><strong>Kepala Keluarga</strong> — pilih dari data penduduk.</li><li><strong>Alamat, RT, RW, Dusun, Kode Pos</strong>.</li><li><strong>Status Ekonomi</strong> &amp; <strong>Penerima Bansos</strong> (untuk klasifikasi kelompok rentan).</li></ul></li><li><strong>Simpan</strong>.</li></ol><h2 id="detail-anggota-keluarga" tabindex="-1">Detail &amp; Anggota Keluarga <a class="header-anchor" href="#detail-anggota-keluarga" aria-label="Permalink to &quot;Detail &amp; Anggota Keluarga&quot;">​</a></h2><p>Halaman detail menampilkan daftar anggota (<code>residents</code> terkait) lengkap dengan status hubungan dalam keluarga. Dari sini Anda bisa:</p><ul><li>Menambah/mengedit anggota — arahkan ke <a href="/panduan-pengguna/penduduk.html">Data Penduduk</a>.</li><li><strong>Mencetak Salinan KK</strong> (PDF).</li></ul><h2 id="mencetak-salinan-kk" tabindex="-1">Mencetak Salinan KK <a class="header-anchor" href="#mencetak-salinan-kk" aria-label="Permalink to &quot;Mencetak Salinan KK&quot;">​</a></h2><p>Klik <strong>Unduh/Cetak PDF</strong> pada KK. Cetakan memuat:</p><ul><li>Kop <strong>Salinan Kartu Keluarga (Register Desa)</strong> — untuk arsip &amp; verifikasi internal desa, <strong>bukan</strong> pengganti KK asli Disdukcapil (Permendagri 47/2016 / UU 24/2013).</li><li>Klausul <em>disclaimer</em> resmi berbingkai.</li><li>TTE/QR pengesahan oleh Kepala Desa.</li><li>Jejak digital: <em>&quot;Diunduh oleh [Nama User] pada [Waktu]&quot;</em>.</li></ul><p>Setiap unduhan tercatat di <a href="/panduan-pengguna/audit-log.html">Audit Log</a> dengan event <code>FamilyPdfDownloaded</code>.</p><div class="warning custom-block"><p class="custom-block-title">Kepatuhan</p><p>Jangan membagikan PDF KK ke pihak yang tidak berkepentingan. Akun RT hanya boleh mengunduh KK warga di RT-nya (otomatis dibatasi sistem).</p></div><h2 id="mengedit-menghapus" tabindex="-1">Mengedit &amp; Menghapus <a class="header-anchor" href="#mengedit-menghapus" aria-label="Permalink to &quot;Mengedit &amp; Menghapus&quot;">​</a></h2><ul><li><strong>Edit</strong> — ubah data inti KK (kepala keluarga, alamat, status sosial-ekonomi).</li><li><strong>Hapus</strong> — hanya untuk data ganda/keliru; pastikan seluruh anggota sudah dipindahkan ke KK lain terlebih dahulu.</li></ul>',17)])])}const p=e(l,[["render",r]]);export{m as __pageData,p as default};
